import{_ as i,C as r,o as n,c as s,j as o,a,E as d,ak as c}from"./chunks/framework.DxrHb2fb.js";const b=JSON.parse('{"title":"动效","description":"","frontmatter":{},"headers":[],"relativePath":"design/motion.md","filePath":"design/motion.md","lastUpdated":1790029076000}'),l={name:"design/motion.md"};function h(u,e,m,x,p,f){const t=r("XhTokenTable");return n(),s("div",null,[e[0]||(e[0]=o("h1",{id:"动效",tabindex:"-1"},[a("动效 "),o("a",{class:"header-anchor",href:"#动效","aria-label":'Permalink to "动效"'},"​")],-1)),e[1]||(e[1]=o("p",null,"动效只做三件事：告诉你按到了、告诉你东西从哪来到哪去、告诉你什么在变。三档时长、一组语义缓动、一条按压时间线、三类浮层进出场——全部是令牌与共享关键帧，皮肤只引用，不自己发明。",-1)),e[2]||(e[2]=o("h2",{id:"时长与缓动",tabindex:"-1"},[a("时长与缓动 "),o("a",{class:"header-anchor",href:"#时长与缓动","aria-label":'Permalink to "时长与缓动"'},"​")],-1)),d(t,{names:["--xh-duration-fast","--xh-duration-normal","--xh-duration-slow"],notes:{"--xh-duration-fast":"微反馈：换面、按下、退场","--xh-duration-normal":"入场、释放、位移","--xh-duration-slow":"大面积滑入：Drawer、Sheet"}}),d(t,{names:["--xh-ease-standard","--xh-ease-out","--xh-ease-out-strong","--xh-ease-out-fluid","--xh-ease-in","--xh-ease-in-out","--xh-ease-out-back"],notes:{"--xh-ease-standard":"连续变化：颜色、按下","--xh-ease-out":"入场","--xh-ease-out-strong":"强入场、释放回弹","--xh-ease-out-fluid":"大面积滑入","--xh-ease-in":"退场","--xh-ease-in-out":"扫过：进度、指示条移动","--xh-ease-out-back":"落定：拖动结束的轻微过冲"}}),e[3]||(e[3]=c('<p>组件不直接取这两组原语，取语义层的 <code>--xh-motion-*</code>：<code>duration-enter / exit / micro / slide / press / release</code>、<code>ease-enter / enter-strong / exit / slide / sweep / press / release / settle / continuous</code>、位移 <code>distance-sm / md</code>（4 / 8px）、缩放 <code>scale-enter 0.96 / exit 0.98 / press 0.97 / drag 1.12</code>、错开起播 <code>stagger-step</code>。CSS 串与 JS 侧 <code>@xihan-ui/motion</code> 的采样函数同一份来源，门禁 <code>check-motion-source</code> 比对。</p><h2 id="按压触感" tabindex="-1">按压触感 <a class="header-anchor" href="#按压触感" aria-label="Permalink to &quot;按压触感&quot;">​</a></h2><p>定尺的独立动作控件（按钮、把手、方框、星、日历格、色块、排序钮）投影 Action Control 配方，按下与释放走同一条时间线：</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">时长</th><th>结果</th><th>缓动</th></tr></thead><tbody><tr><td>按下</td><td style="text-align:right;">120ms（<code>--xh-motion-duration-press</code>）</td><td>scale 1 → 0.97，底进入 active</td><td><code>--xh-motion-ease-press</code></td></tr><tr><td>释放</td><td style="text-align:right;">200ms（<code>--xh-motion-duration-release</code>）</td><td>scale 0.97 → 1，底回到 hover / rest</td><td><code>--xh-motion-ease-release</code></td></tr></tbody></table><ul><li>transform origin 固定居中；指针 <code>:active</code>、键盘 Space / Enter 与 Headless 投影的 <code>data-pressed</code> 三者一致。</li><li>行级条目与 disclosure trigger（菜单项、树节点、表格行、手风琴标题）只换面，不缩放整个条目；不允许零反馈。</li><li>不用点击波纹；不允许组件自设 0.94 / 0.96 / 0.98 等缩放。</li><li>业务事件不等动画结束：按下首帧先于异步 loading 可见；pending 后锁定重复操作，不持续缩放。</li><li>hover + pressed 时 pressed 优先；focus-visible + pressed 保留焦点环、按压只改内部表面；selected / danger + pressed 保留各自身份，在其上派生 active 面。</li></ul><h2 id="disclosure" tabindex="-1">Disclosure <a class="header-anchor" href="#disclosure" aria-label="Permalink to &quot;Disclosure&quot;">​</a></h2><ul><li>Surface 级展开（Accordion、Collapsible、Reasoning、ToolCall）内容走 <code>grid-template-rows: 0fr → 1fr</code>：入场 <code>--xh-motion-duration-enter</code> + <code>--xh-motion-ease-enter-strong</code>，退场 <code>--xh-motion-duration-exit</code> + <code>--xh-motion-ease-exit</code>；指示器旋转与内容同档。</li><li>密集树形展开（Tree、TreeSelect、JsonViewer、SideNav 内联子层）不动高度，只旋转指示器 <code>--xh-motion-duration-micro</code>。</li></ul><h2 id="浮层进出场" tabindex="-1">浮层进出场 <a class="header-anchor" href="#浮层进出场" aria-label="Permalink to &quot;浮层进出场&quot;">​</a></h2><p>按锚定关系三分，关键帧集中在 <code>family/motion.css</code>，皮肤不得重定义：</p><table tabindex="0"><thead><tr><th>关系</th><th>关键帧</th><th>组件</th></tr></thead><tbody><tr><td>锚定列表 / 菜单</td><td><code>xh-overlay-slide-in / out</code></td><td>Menu、Select、Combobox、Cascader、ContextMenu、Menubar、Mention、TreeSelect、Date / Time picker、Tooltip</td></tr><tr><td>锚定面板</td><td><code>xh-overlay-pop-in</code> / <code>xh-pop-out</code></td><td>Popover、HoverCard、Popconfirm、Tour、Command</td></tr><tr><td>无锚定弹出</td><td><code>xh-pop-in / out</code></td><td>NavigationMenu、SideNav popout、FloatingPanel、FloatButton 列表、Pagination 弹层</td></tr></tbody></table><p>遮罩与全屏面 <code>xh-fade-in / out</code>；Dialog / Notification = 位移 md + <code>scale-enter</code>；Drawer 入场 <code>--xh-motion-duration-slide</code> + <code>--xh-motion-ease-slide</code>、退场 <code>--xh-motion-duration-exit</code> + <code>--xh-motion-ease-exit</code>。退场由 Presence 等动画真正结束再卸载节点。</p><h2 id="弹簧与-js-动画" tabindex="-1">弹簧与 JS 动画 <a class="header-anchor" href="#弹簧与-js-动画" aria-label="Permalink to &quot;弹簧与 JS 动画&quot;">​</a></h2><p>指针跟手的东西（拖动、滑杆、轮播惯性）不用固定时长，用 <code>@xihan-ui/motion</code> 的弹簧：由刚度、阻尼与质量算终点，中途换目标不跳帧。<code>animate()</code> 默认取 <code>durations.normal</code>，<code>@xihan-ui/animations</code> 的配方默认取 <code>durations.slow</code>。见 <a href="/guide/motion">动效原语</a> 与 <a href="/guide/animations">动画层</a>。</p><h2 id="减弱动效" tabindex="-1">减弱动效 <a class="header-anchor" href="#减弱动效" aria-label="Permalink to &quot;减弱动效&quot;">​</a></h2><p><code>data-motion=&quot;reduce&quot;</code>（偏好 <code>system</code> 时跟 <code>prefers-reduced-motion</code>）取消位移与缩放，保留即时换面：按下仍然换底、浮层仍然出现，只是不再滑动与缩放。JS 侧经 <code>resolveMotionPreference</code> 读同一个值——退场租约、贴底滚动、数字动画、加载弧线、背景层全部走这一条通道，产品自己的&quot;减弱动效&quot;设置用 <code>setMotionOverride</code> 一处设置、处处生效。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/design/shadow">阴影与材质</a> · <a href="/design/patterns">组件家族与模式</a></li><li>指南：<a href="/guide/motion">动效原语</a> · <a href="/guide/animations">动画层</a> · <a href="/guide/theme#点击触感">设计令牌与主题 · 点击触感</a></li></ul>',17))])}const S=i(l,[["render",h]]);export{b as __pageData,S as default};
